"""Read-only neatlogs MCP client: tools/list. No model calls, no writes."""
import json
import urllib.request

URL = "https://ingest.neatlogs.com/mcp"


def load_key():
    for line in open(".env", encoding="utf-8"):
        line = line.strip()
        if line.startswith("NEATLOGS_API_KEY="):
            return line.split("=", 1)[1].strip().strip('"').strip("'")
    raise SystemExit("no key")


def post(body, sid=None):
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream",
        "Authorization": "Bearer " + load_key(),
    }
    if sid:
        headers["Mcp-Session-Id"] = sid
    req = urllib.request.Request(
        URL, data=json.dumps(body).encode(), headers=headers)
    with urllib.request.urlopen(req, timeout=30) as resp:
        return resp.headers.get("Mcp-Session-Id"), resp.read().decode()


def rpc(method, params, sid, rid):
    _, out = post({"jsonrpc": "2.0", "id": rid,
                   "method": method, "params": params}, sid)
    for line in out.splitlines():
        if line.startswith("data: "):
            return json.loads(line[len("data: "):])
    raise SystemExit("no data in: " + out[:200])


if __name__ == "__main__":
    sid, _ = post({"jsonrpc": "2.0", "id": 1, "method": "initialize",
                   "params": {"protocolVersion": "2024-11-05",
